&lt;/a&gt;
&lt;h2 class=&quot;separator&quot;&gt;R&#232;gles de l&#39;intrigue&lt;a class=&quot;headeranchor&quot; id=&quot;R&#232;gles_de_lintrigue_0&quot; href=&quot;#R&#232;gles_de_lintrigue_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;ul&gt;&lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;boutonMa&#238;trise&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;Ma&#238;trise&#39;);&quot; onmouseout=&quot;outButton(&#39;Ma&#238;trise&#39;);&quot; onclick=&quot;expandMenu(&#39;Ma&#238;trise&#39;);&quot; /&gt;
&lt;/div&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;triser-Lintrigue.html&quot; title=&quot;Ma&#238;triser l&amp;#39;intrigue&quot;&gt;Ma&#238;triser l&#39;intrigue&lt;/a&gt;&amp;emsp;
        &lt;ul ID=&quot;Ma&#238;trise&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Influence.html&quot; title=&quot;L&amp;#39;influence&quot;&gt;L&#39;influence&lt;/a&gt;&lt;/li&gt;
            &lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Influence-Individuelle.html&quot; title=&quot;L&amp;#39;influence individuelle&quot;&gt;L&#39;influence individuelle&lt;/a&gt;&lt;/li&gt;
                &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Influence-Organisationnelle.html&quot; title=&quot;L&amp;#39;influence organisationnelle&quot;&gt;L&#39;influence organisationnelle&lt;/a&gt;&lt;/li&gt;
            &lt;/ul&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Casses.html&quot; title=&quot;Les casses&quot;&gt;Les casses&lt;/a&gt;&lt;/li&gt;
            &lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Casses,-Infiltration.html&quot; title=&quot;L&amp;#39;infiltration (Casses)&quot;&gt;L&#39;infiltration&lt;/a&gt;&lt;/li&gt;
            &lt;/ul&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Prestige-Ui.html&quot; title=&quot;Le prestige&quot;&gt;Le prestige&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;N&#233;m&#233;sis-Ui.html&quot; title=&quot;Les n&#233;m&#233;sis&quot;&gt;Les n&#233;m&#233;sis&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poursuites.html&quot; title=&quot;Les poursuites&quot;&gt;Les poursuites&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Recherches.html&quot; title=&quot;Les recherches&quot;&gt;Les recherches&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorts-Dintrigue.html&quot; title=&quot;Les sorts d&amp;#39;intrigue&quot;&gt;Les sorts d&#39;intrigue&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Conflits-Sociaux.html&quot; title=&quot;Les conflits sociaux&quot;&gt;Conflits sociaux&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Duels-Verbaux.html&quot; title=&quot;Les duels verbaux&quot;&gt;Duels verbaux&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences-En-Conflit.html&quot; title=&quot;Les comp&#233;tences en conflit&quot;&gt;Comp&#233;tences en conflit&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;table id=&quot;TocContainerTable&quot;&gt;&lt;tr&gt;&lt;td&gt;&lt;div id=&quot;TocContainer&quot;&gt;&lt;p class=&quot;small&quot;&gt;&lt;b&gt;Table of Contents&lt;/b&gt;&lt;span id=&quot;ExpandTocSpan&quot;&gt; [&lt;a href=&quot;#&quot; onclick=&quot;javascript:if(document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]==&#39;none&#39;) document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;&#39;; else document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;none&#39;; return false;&quot;&gt;Hide/Show&lt;/a&gt;]&lt;/span&gt;&lt;/p&gt;&lt;div id=&quot;Toc&quot;&gt;&lt;p&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Les_syst&#232;mes_dintrigue_10&quot;&gt;Les syst&#232;mes d&#39;intrigue&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Les_&#233;l&#233;ments_dintrigue_11&quot;&gt;Les &#233;l&#233;ments d&#39;intrigue&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Relations_et_all&#233;geances_0&quot;&gt;Relations et all&#233;geances&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mesures_et_contre-mesures_1&quot;&gt;Mesures et contre-mesures&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Limportance_des_apparences_2&quot;&gt;L&#39;importance des apparences&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Marchandage_et_compromis_3&quot;&gt;Marchandage et compromis&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Le_pouvoir_des_secrets_4&quot;&gt;Le pouvoir des secrets&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Les_th&#232;mes_dintrigue_12&quot;&gt;Les th&#232;mes d&#39;intrigue&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Un_jeu_de_nobles_5&quot;&gt;Un jeu de nobles&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Le_monde_criminel_6&quot;&gt;Le monde criminel&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Guerre_et_propagande_7&quot;&gt;Guerre et propagande&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Loi_et_Ordre_8&quot;&gt;Loi et Ordre&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Intrigue_ultime_9&quot;&gt;Intrigue ultime&lt;/a&gt;&lt;br /&gt;&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;Toute aventure peut contenir des &#233;l&#233;ments d&#39;intrigue, et m&#234;me le donjon le plus centr&#233; sur les combats peut profiter d&#39;une rupture avec des rencontres plus nuanc&#233;es pour changer de rythme. Parce qu&#39;elle est moins conflictuelle que le combat physique, l&#39;intrigue agit comme un contrepoint aux rencontres habituelles, et sert &#224; mettre en valeur et &#224; renforcer les &#233;tapes les plus intenses d&#39;une campagne, aidant la tension &#224; monter lentement et naturellement et cr&#233;ant des moments de narration satisfaisants.&lt;br /&gt;&lt;br /&gt;Toutes les r&#233;f&#233;rences &#224; &quot;un jeu bas&#233; sur l&#39;intrigue&quot; dans la section suivante s&#39;appliquent &#224; un jeu qui incorpore n&#39;importe quelle quantit&#233; d&#39;intrigue, d&#39;un jeu avec un soup&#231;on de fourberie &#224; un thriller politique assum&#233;.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Les syst&#232;mes d&#39;intrigue&lt;a class=&quot;headeranchor&quot; id=&quot;Les_syst&#232;mes_dintrigue_10&quot; href=&quot;#Les_syst&#232;mes_dintrigue_10&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Ce chapitre contient de nouveaux sous-syst&#232;mes, de nouvelles r&#232;gles et de conseils pour ajouter de solides &#233;l&#233;ments d&#39;intrigue &#224; votre partie.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Influence.html&quot; title=&quot;L&amp;#39;influence&quot;&gt;L&#39;influence&lt;/a&gt;.&lt;/b&gt; Ce syst&#232;me de r&#232;gles mesure la fa&#231;on dont les personnages gagnent en influence et en r&#233;putation aupr&#232;s de diverses organisations. Plut&#244;t que de r&#233;duire une interaction sociale &#224; un ou deux tests de comp&#233;tence, l&#39;influence cr&#233;e un &#233;change qui se d&#233;roule sur une sc&#232;ne plus longue. Il fournit des r&#233;compenses concr&#232;tes pour l&#39;engagement avec de tels groupes, qui peuvent &#234;tre personnalis&#233;es pour s&#39;adapter &#224; votre partie.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Casses.html&quot; title=&quot;Les casses&quot;&gt;Les casses&lt;/a&gt;.&lt;/b&gt; Cette section pr&#233;sente des conseils sur l&#39;organisation et l&#39;ex&#233;cution de casses, comme l&#39;escroquerie ou la violation d&#39;un ensemble de d&#233;fenses complexes pour voler un objet, secourir une personne ou atteindre un autre objectif. Cette section aborde &#233;galement le sujet similaire de l&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Casses,-Infiltration.html&quot; title=&quot;L&amp;#39;infiltration (Casses)&quot;&gt;infiltration&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Prestige-Ui.html&quot; title=&quot;Le prestige&quot;&gt;Le prestige&lt;/a&gt;.&lt;/b&gt; S&#39;appuyant sur le don &lt;a class=&quot;pagelink&quot; href=&quot;Prestige.html&quot; title=&quot;Prestige&quot;&gt;Prestige&lt;/a&gt;, cette section propose des moyens d&#39;incorporer le prestige dans le jeu afin que les PJs puissent attirer des mercenaires et d&#39;autres suivants. D&#233;couvrez des conseils sur la fa&#231;on dont le prestige fonctionne dans un jeu bas&#233; sur l&#39;intrigue, et le r&#244;le que les compagnons d&#39;arme et les suivants peuvent jouer dans de telles campagnes.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;N&#233;m&#233;sis-Ui.html&quot; title=&quot;Les n&#233;m&#233;sis&quot;&gt;Les n&#233;m&#233;sis&lt;/a&gt;.&lt;/b&gt; Afin de sublimer les coups de th&#233;&#226;tre et les parades d&#39;une relation conflictuelle, le syst&#232;me de n&#233;m&#233;sis ajoute des stratag&#232;mes vicieux qu&#39;un ennemi peut employer contre le groupe. Cette section contient &#233;galement des suggestions pour faire monter l&#39;animosit&#233;, ainsi que des strat&#233;gies sp&#233;cifiques et des r&#233;compenses en XP.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poursuites.html&quot; title=&quot;Les poursuites&quot;&gt;Les poursuites&lt;/a&gt;.&lt;/b&gt; Pour les courses poursuites de longue dur&#233;e qui s&#39;&#233;tendent sur plusieurs jours, ces nouvelles r&#232;gles de poursuite rendent les &#233;changes de ces situations amusants et strat&#233;giques, offrant des opportunit&#233;s de prendre l&#39;avantage sur les poursuivants ou les proies.&lt;br /&gt;&lt;br /&gt;
&lt;b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Recherches.html&quot; title=&quot;Les recherches&quot;&gt;Les recherches&lt;/a&gt;.&lt;/b&gt; Des informations obscures sont cach&#233;es dans les grandes biblioth&#232;ques et autres archives de connaissances. Le syst&#232;me de recherche propose une proc&#233;dure pour creuser dans les tomes anciens et glaner ces informations rares.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorts-Dintrigue.html&quot; title=&quot;Les sorts d&amp;#39;intrigue&quot;&gt;Les sorts d&#39;intrigue&lt;/a&gt;.&lt;/b&gt; De nombreux sorts posent probl&#232;me dans un jeu bas&#233; sur l&#39;intrigue en permettant aux personnages de d&#233;tecter facilement des mensonges, de charmer des cr&#233;atures qui ont les informations primordiales, ou de contourner d&#39;une autre mani&#232;re les interactions sociales. Cette section traite de ces sorts &#224; la fois en termes g&#233;n&#233;raux et en termes sp&#233;cifiques pour aider le MJ &#224; y r&#233;agir.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Les &#233;l&#233;ments d&#39;intrigue&lt;a class=&quot;headeranchor&quot; id=&quot;Les_&#233;l&#233;ments_dintrigue_11&quot; href=&quot;#Les_&#233;l&#233;ments_dintrigue_11&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les &#233;l&#233;ments suivants sont des ingr&#233;dients qui peuvent contribuer &#224; ajouter de l&#39;intrigue &#224; votre partie. Vous pouvez utiliser un seul &#233;l&#233;ment pour introduire des complications dans une partie ou une session autrement peu intrigante, ou en combiner plusieurs pour tisser une toile d&#39;intrigue complexe tout au long de votre campagne.&lt;br /&gt;&lt;br /&gt;M&#234;me un groupe principalement orient&#233; vers l&#39;exploration de donjons peut &#234;tre impliqu&#233; dans une lutte de pouvoir dans la ville o&#249; il a &#233;lu domicile, ou &#234;tre coinc&#233; entre deux rivaux qui tentent d&#39;utiliser les PJs comme patte de chat pour tirer les marrons du feu. Dans une campagne qui n&#39;utilise qu&#39;un seul &#233;l&#233;ment pour un peu de fantaisie, il est important d&#39;incorporer cet &#233;l&#233;ment de fa&#231;on r&#233;guli&#232;re, mais pas n&#233;cessairement &#224; chaque session.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Relations et all&#233;geances&lt;a class=&quot;headeranchor&quot; id=&quot;Relations_et_all&#233;geances_0&quot; href=&quot;#Relations_et_all&#233;geances_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Dans un jeu bas&#233; sur l&#39;intrigue, les relations interpersonnelles sont mises en avant et servent une vari&#233;t&#233; de r&#244;les et de buts diff&#233;rents. La fa&#231;on dont les r&#233;actions et les sentiments des gens changent avec le temps et l&#39;interaction est y au cœur de l&#39;intrigue, plut&#244;t que quelque chose &#224; ignorer ou &#224; r&#233;soudre par un simple jet. Les relations et la loyaut&#233; peuvent laisser des traces dans une campagne de plusieurs fa&#231;ons.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;R&#233;compenses non mon&#233;taires.&lt;/b&gt; Les relations avec d&#39;autres personnages et les avantages et privil&#232;ges accord&#233;s par ces relations sont des r&#233;compenses fondamentales, tout aussi pr&#233;cieuses, voire plus, que de simples pi&#232;ces de monnaie. Les bons amis peuvent donner acc&#232;s &#224; des &#233;v&#233;nements sociaux, offrir des cadeaux, fournir des informations, faire dispara&#238;tre des probl&#232;mes ou accomplir diverses autres faveurs pour le compte d&#39;un personnage. Parfois, une amiti&#233; peut devenir plus encore, et cela peut repr&#233;senter une r&#233;compense en tant que tel.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;All&#233;geances et tension.&lt;/b&gt; Tous les personnages ont leurs propres objectifs et leurs propres all&#233;geances, m&#234;me ceux qui sont alli&#233;s aux PJs. Les personnages agissent et r&#233;pondent aux &#233;v&#233;nements du monde qui les entoure de mani&#232;re &#224; servir leurs int&#233;r&#234;ts et &#224; correspondre &#224; leur vision du monde. Une partie de la tension de telles parties provient de l&#39;incertitude sur la fa&#231;on dont les autres vont agir, en particulier &#224; un moment d&#233;cisif o&#249; des all&#233;geances contradictoires s&#39;affrontent. Les PJs voleurs peuvent-ils faire confiance &#224; leur ami de la garde pour ne pas craquer lorsque son commandant fait pression sur lui, ou va-t-il r&#233;v&#233;ler ce qu&#39;il sait ? La princesse que les PJs ont aid&#233;e &#224; acc&#233;der au tr&#244;ne tiendra-t-elle la promesse faite aux PJ d&#39;accorder l&#39;asile aux sorci&#232;res maintenant qu&#39;elle est reine, ou reviendra-t-elle &#224; la position la plus populaire lorsque les ducs menaceront de faire s&#233;cession ? L&#39;intendant d&#39;un PJ va-t-il c&#233;der aux menaces d&#39;un baron du crime contre sa famille kidnapp&#233;e et d&#233;tourner secr&#232;tement l&#39;argent des PJ, ou va-t-il les informer et risquer la s&#233;curit&#233; de ses proches ?&lt;br /&gt;&lt;br /&gt;La fa&#231;on dont les PNJs r&#233;agissent dans ces situations de haute pression sert &#233;galement &#224; les caract&#233;riser et &#224; les humaniser. Si un PNJ se range du c&#244;t&#233; des PJ dans l&#39;une de ces situations, il a fait une d&#233;monstration puissante de sa loyaut&#233; envers les PJs. Si les PJs ont gagn&#233; cette loyaut&#233; en tant que r&#233;compense, cela servira &#224; renforcer les accomplissements des PJ. Dans tous les cas, cela impressionnera probablement les PJs et les rapprochera du PNJ. M&#234;me si le PNJ c&#232;de, cela ne fait pas de lui un m&#233;chant, et il pourrait catapulter son r&#244;le dans celui d&#39;un adversaire r&#233;ticent des PJs avec un discours significatif.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Trahison.&lt;/b&gt; Contrairement &#224; un ancien alli&#233; contraint par les circonstances et des all&#233;geances contradictoires &#224; agir contre l&#39;int&#233;r&#234;t des PJs, rien n&#39;inspire la haine d&#39;un PNJ plus qu&#39;une bonne vieille trahison. Qu&#39;il s&#39;agisse d&#39;un PNJ qui engage les PJs sous de faux pr&#233;textes pour les pi&#233;ger ou d&#39;un alli&#233; apparent qui fournit des informations &#224; l&#39;ennemi, un tra&#238;tre fait monter les ench&#232;res et suscite une r&#233;action &#233;motionnelle puissante.&lt;br /&gt;&lt;br /&gt;Bien s&#251;r, la trahison est beaucoup plus int&#233;ressante si elle est l&#39;exception, plut&#244;t que la r&#232;gle. Si les PNJs trahissent trop souvent les PJs, vous sapez l&#39;accent mis sur les relations dans la campagne en faisant regretter aux PJ les efforts qu&#39;ils ont d&#233;ploy&#233;s pour &#233;tablir des alliances avec les PNJs et gagner leur loyaut&#233;. L&#39;exception &#224; cette r&#232;gle est un jeu plus cynique, o&#249; les alliances sont n&#233;cessaires pour survivre, mais o&#249; la trahison est le statu quo. Lorsque vous organisez une telle partie, il est essentiel que les joueurs le sachent &#224; l&#39;avance, ou au moins peu de temps apr&#232;s la premi&#232;re fois qu&#39;ils ont affaire aux aspects cyniques et perfides de la soci&#233;t&#233;. M&#234;me dans ces parties, bien que la possibilit&#233; de trahison soit omnipr&#233;sente et constamment pr&#233;sente &#224; l&#39;esprit des joueurs et des personnages, toutes les relations ne doivent pas se terminer par une trahison, sinon elles perdent rapidement leur impact.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Hi&#233;rarchies.&lt;/b&gt; La hi&#233;rarchie est un syst&#232;me structur&#233; d&#39;all&#233;geances, qu&#39;elles soient politiques, sociales, militaires ou d&#39;une autre nature. La progression dans une hi&#233;rarchie est un excellent moyen de suivre les r&#233;compenses non mon&#233;taires dans un jeu bas&#233; sur l&#39;intrigue. Les hi&#233;rarchies sont &#233;galement une excellente source d&#39;intrigues int&#233;ressantes et d&#39;all&#233;geances contradictoires, dans les deux sens de la hi&#233;rarchie. Devenir membre d&#39;une hi&#233;rarchie donne aux PJs un fort sentiment d&#39;appartenance et une raison d&#39;agir et de poursuivre une aventure d&#39;intrigue. Les ennemis op&#233;rant au sein d&#39;une hi&#233;rarchie font d&#39;excellents adversaires, car leur appartenance &#224; la hi&#233;rarchie peut &#234;tre tour &#224; tour une source de force et une vuln&#233;rabilit&#233;. Si l&#39;ennemi et un PJ sont tous deux membres de la m&#234;me hi&#233;rarchie, les choses peuvent devenir particuli&#232;rement int&#233;ressantes, les deux personnages &#233;tant &#224; la fois renforc&#233;s et limit&#233;s par leur place dans le syst&#232;me.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Mesures et contre-mesures&lt;a class=&quot;headeranchor&quot; id=&quot;Mesures_et_contre-mesures_1&quot; href=&quot;#Mesures_et_contre-mesures_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Dans les jeux bas&#233; sur l&#39;intrigue, les adversaires se livrent &#224; des activit&#233;s clandestines et cherchent &#224; emp&#234;cher leurs actions respectives. Tout comme dans le monde r&#233;el, l&#39;invention de nouvelles mesures et contre-mesures conduit &#224; des affrontements secrets et croissants qui se d&#233;roulent sous la surface, chaque partie cherchant &#224; exploiter les vuln&#233;rabilit&#233;s de l&#39;autre ou &#224; renforcer les siennes. Dans un monde imaginaire, ces avanc&#233;es peuvent &#234;tre aussi bien magiques que banales, qu&#39;il s&#39;agisse d&#39;une nouvelle fa&#231;on de coder les informations ou d&#39;un sort qui contourne la s&#233;curit&#233; de l&#39;ennemi. &#192; cet &#233;gard, il peut &#234;tre amusant d&#39;inclure de nouveaux sorts, peut-&#234;tre tir&#233;s d&#39;un grimoire obscur, ou m&#234;me invent&#233;s par un PJ. Mais une fois que les adversaires des PJs l’ont compris, ils finissent par trouver une parade, et le cycle continue.&lt;br /&gt;&lt;br /&gt;Soyez prudent lorsque vous utilisez cet &#233;l&#233;ment. Id&#233;alement, vous voulez que les adversaires des PJ participent &#224; cette course &#224; l&#39;armement de l&#39;intrigue &#224; peu pr&#232;s au m&#234;me rythme que les PJs, afin qu&#39;ils aient l&#39;air de rivaux cr&#233;dibles, plut&#244;t que d&#39;incomp&#233;tents arrivistes. Si les PJs ne sont pas du tout int&#233;ress&#233;s par cet aspect, ne faites pas en sorte que les PNJs poursuivent l&#39;escalade. Ce conseil vaut m&#234;me pour les sorts les plus communs du &lt;i&gt;Manuel des joueurs&lt;/i&gt;. Les PJs et les pr&#233;cautions qu&#39;ils prennent et attendent sont un indicateur des pr&#233;cautions approximatives que les PNJs devraient prendre.&lt;br /&gt;&lt;br /&gt;L&#39;exception &#233;tant lorsqu&#39;on essaie d&#39;introduire la notion de mesures et de contre-mesures &#224; un groupe de jeu qui ne les utilise pas habituellement ou qui est compos&#233; de nouveaux joueurs qui ne sont pas familiers avec tous les sorts et outils &#224; leur disposition. Pour un tel groupe, la premi&#232;re fois qu&#39;ils apprennent &#224; utiliser des contre-mesures de base pourrait &#234;tre lorsqu&#39;un PNJ les a utilis&#233;es. Par exemple, disons que les PJs commencent une enqu&#234;te sur un crime &#224; la demande d&#39;un PNJ ; le PNJ pourrait commencer par dire aux PJs quelles mesures d&#39;investigation il a d&#233;j&#224; prises - et donc quelles contre-mesures il soup&#231;onne l&#39;auteur du crime d&#39;avoir utilis&#233;. Cela permet aux PJs de d&#233;couvrir ces mesures et contre-mesures de mani&#232;re transparente, comme un &#233;l&#233;ment &#233;tabli de l&#39;univers du jeu, plut&#244;t qu&#39;un obstacle qui surgit de nulle part au cours de la partie. Avec ce genre d&#39;introduction, vous pouvez concevoir une intrigue qui tourne autour du contournement ou de l&#39;exploitation de ces contre-mesures d&#232;s le d&#233;part.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;L&#39;importance des apparences&lt;a class=&quot;headeranchor&quot; id=&quot;Limportance_des_apparences_2&quot; href=&quot;#Limportance_des_apparences_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Dans certaines parties, le succ&#232;s et l&#39;&#233;chec se mesurent &#224; l&#39;aune de l&#39;opinion publique, et il est souvent plus important de para&#238;tre d&#39;une fa&#231;on que de l&#39;&#234;tre r&#233;ellement. Cela conduit &#224; de nombreuses tromperies et trahisons, et peut &#233;galement conduire &#224; des guerres de croyances populaires, dans lesquelles les deux camps cherchent &#224; d&#233;peindre l&#39;autre comme le m&#233;chant et o&#249; les opinions subjectives l&#39;emportent sur la v&#233;rit&#233;. Dans ces situations, il est important de pouvoir sauver les apparences, ce qui est une comp&#233;tence cl&#233; dans un groupe d&#39;aventuriers ax&#233; sur l&#39;intrigue. La n&#233;cessit&#233; des apparences restreint souvent certaines actions qu&#39;un groupe peut entreprendre, ce qui se traduit par des tactiques indirectes, discr&#232;tes et inhabituelles, plut&#244;t que de se pr&#233;cipiter dans la maison d&#39;un adversaire et d&#39;an&#233;antir tout le monde &#224; coups d&#39;acier et de sorts. Utiliser la pression sociale pour restreindre les actions envisag&#233;es est un excellent moyen de mettre en valeur les comp&#233;tences et les capacit&#233;s vari&#233;es de chaque membre du groupe, pour autant que ces restrictions aient un sens et s&#39;int&#232;grent &#224; la mani&#232;re dont la situation est structur&#233;e. Par exemple, si les PJs veulent aider la jeune sœur du duc mal&#233;fique &#224; susciter la dissidence contre le duc en prouvant que celui-ci est coupable du meurtre de son majordome, assassiner les fid&#232;les serviteurs du duc et le nouveau majordome ferait passer les PJs pour des hypocrites (ainsi que pour des maniaques d&#233;sesp&#233;r&#233;s), et n&#39;est donc pas une tactique judicieuse. De m&#234;me, si un certain type de magie, comme la n&#233;cromancie ou les coercitions, est ill&#233;gal dans une soci&#233;t&#233;, il est logique que les PJs doivent utiliser ces tactiques avec parcimonie pour &#233;viter que leurs actes ne soient &#233;clips&#233;s par leurs utilisations ill&#233;gales de la magie.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Marchandage et compromis&lt;a class=&quot;headeranchor&quot; id=&quot;Marchandage_et_compromis_3&quot; href=&quot;#Marchandage_et_compromis_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Dans une campagne qui tourne autour du combat physique entre le bien et le mal, il y a peu de place pour les compromis. Mais dans un jeu bas&#233; sur l&#39;intrigue, o&#249; chaque personnage agit en fonction de ses int&#233;r&#234;ts et de ses all&#233;geances, il arrive un moment o&#249; les choses sont &#233;videntes, o&#249; un adversaire raisonnable propose un march&#233; plut&#244;t que de suivre la lutte jusqu&#39;&#224; la destruction. Ces compromis peuvent m&#234;me offrir aux PJ plus que ce qu&#39;ils obtiendraient en d&#233;truisant leur ennemi, tout en permettant &#224; ce dernier de conserver ce qui est le plus important pour lui. Dans la plupart des campagnes, les PJs vont gagner, mais ce genre d&#39;offre est une excellente occasion pour les PJs d&#39;&#233;tablir leurs priorit&#233;s et de prendre une vraie d&#233;cision sur la fa&#231;on dont ils vont gagner. Par exemple, supposons que l&#39;objectif principal des PJ est d&#39;&#233;manciper les esclaves, et qu&#39;au cours de ce conflit, la faction pro-esclavagiste soudoie un magistrat influent pour rendre la vie difficile aux PJ. Les PJs sont capables de renverser la situation et de d&#233;couvrir des preuves accablantes qui pourraient d&#233;truire la carri&#232;re de la magistrate &#224; jamais. La magistrate propose donc un march&#233; aux PJ : s&#39;ils ne divulguent pas les preuves et lui permettent de garder son poste, elle utilisera son influence pour aider &#224; l&#39;&#233;mancipation des halfelins et donnera aux PJ un avantage consid&#233;rable. Les PJs peuvent-ils lui faire confiance ? Qu&#39;est-ce qui est le plus fort, leur d&#233;sir d&#39;aider les halfelins, ou leur d&#233;sir de voir la magistrate obtenir sa juste fin ?&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Le pouvoir des secrets&lt;a class=&quot;headeranchor&quot; id=&quot;Le_pouvoir_des_secrets_4&quot; href=&quot;#Le_pouvoir_des_secrets_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les secrets sont puissants dans toutes les parties de Pathfinder, m&#234;me celles enti&#232;rement ax&#233;es sur le combat, car leur d&#233;couverte permet aux personnages de conna&#238;tre les forces et les faiblesses de l&#39;ennemi et de planifier en cons&#233;quence. Cependant, lorsque vous utilisez l&#39;intrigue dans votre jeu, les secrets sont encore plus significatifs. En fait, un secret vraiment puissant peut repr&#233;senter une r&#233;compense bien plus importante que le tr&#233;sor d&#39;un dragon. Les secrets sont li&#233;s &#224; tous les autres &#233;l&#233;ments d&#39;un jeu bas&#233; sur l&#39;intrigue. Ils peuvent d&#233;truire des relations et bousculer les all&#233;geances, souvent &#224; l&#39;avantage de celui qui d&#233;tient ou divulgue le secret. La divulgation d&#39;un secret peut briser la fausse apparence de quelqu&#39;un. Par exemple, quel que soit le bonus des PJ en &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt;, leurs seuls mots ne peuvent pas persuader la gentille et fid&#232;le reine d&#39;aider &#224; assassiner ou &#224; &#233;vincer son mari, un roi mal&#233;fique qui a convaincu tout le monde - m&#234;me sa femme, qu&#39;il aime vraiment - qu&#39;il est un homme bon. Mais si les PJs exposent les sombres secrets du roi de mani&#232;re convaincante, puis r&#233;ussissent &#224; influencer la reine, ils pourraient bien r&#233;ussir. Les secrets font &#233;galement partie int&#233;grante des complots de chantage, qui peuvent conduire &#224; des n&#233;gociations fascinantes et &#224; des accords en coulisses. Bien entendu, si le recours &#224; l&#39;extorsion peut vous permettre de vous faire une sorte d&#39;alli&#233;, ces alliances sont fond&#233;es sur la mauvaise volont&#233;. En raison des dangers li&#233;s aux fuites de secrets, la protection des secrets est l&#39;un des principaux moteurs de la course aux mesures et contre-mesures &#233;voqu&#233;e plus haut. Et, bien s&#251;r, la chose la plus dangereuse qu&#39;un personnage puisse faire est de d&#233;couvrir un secret que quelqu&#39;un de puissant ne veut voir expos&#233;.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Les th&#232;mes d&#39;intrigue&lt;a class=&quot;headeranchor&quot; id=&quot;Les_th&#232;mes_dintrigue_12&quot; href=&quot;#Les_th&#232;mes_dintrigue_12&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Si les &#233;l&#233;ments d&#39;intrigue sont des ingr&#233;dients, les th&#232;mes d&#39;intrigue suivants sont des exemples de recettes qui combinent ces composants de diverses mani&#232;res sp&#233;cifiques, ouvrant la porte &#224; des aventures et des campagnes qui plongent plus profond&#233;ment dans le monde de l&#39;intrigue que celles qui ne contiennent qu&#39;un simple saupoudrage d&#39;&#233;l&#233;ments ici et l&#224;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Un jeu de nobles&lt;a class=&quot;headeranchor&quot; id=&quot;Un_jeu_de_nobles_5&quot; href=&quot;#Un_jeu_de_nobles_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;S&#39;aventurer dans les machinations de la noblesse, avec ses doubles jeux et ses complots &#233;go&#239;stes, combine les &#233;l&#233;ments Relations et all&#233;geances, L&#39;importance des apparences, Marchandage et compromis, et Le pouvoir des secrets. Que les PJs commencent en tant que membres de la noblesse, gardes et serviteurs cherchant &#224; am&#233;liorer leur statut et leur fortune, enfants ill&#233;gitimes esp&#233;rant revendiquer les titres de leurs parents nobles, ou simplement aventuriers engag&#233;s par la mauvaise maison noble, ils s&#39;emp&#234;trent rapidement dans une tapisserie de pouvoir et de trahison. Dans ce th&#232;me, comme les principaux acteurs exercent une grande influence, les enjeux sont extr&#234;mement &#233;lev&#233;s, ce qui permet m&#234;me &#224; des PJ de bas niveau de devenir des acteurs importants, &#224; condition qu&#39;ils sachent jouer le jeu. Lorsque vous utilisez ce th&#232;me, il est entendu que chacun a ses propres objectifs et tente d&#39;am&#233;liorer son statut personnel, de sorte que les actions &#233;go&#239;stes sont le statu quo, tandis que les moments de v&#233;ritable sacrifice et de loyaut&#233; sont rares et touchants. Avec les mar&#233;es changeantes de la politique, un ennemi d&#39;aujourd&#39;hui peut &#234;tre un ami de demain, et il est probable que de nombreux personnages seront neutres sur l&#39;axe Bien/Mal, ou du moins seulement l&#233;g&#232;rement bons ou mauvais, ce qui brouille les pistes et rend le choix de qui soutenir moins &#233;vident.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Le monde criminel&lt;a class=&quot;headeranchor&quot; id=&quot;Le_monde_criminel_6&quot; href=&quot;#Le_monde_criminel_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Bien qu&#39;elle puisse b&#233;n&#233;ficier de l&#39;utilisation d&#39;autres &#233;l&#233;ments, une campagne se d&#233;roulant dans le monde criminel est fondamentalement construite autour des tensions des &#233;l&#233;ments Relations et all&#233;geances, Mesures et contre-mesures, et Marchandage et compromis. L&#39;importance de maintenir une apparence publique positive emp&#234;che un noble de s&#39;engager dans trop d&#39;activit&#233;s illicites, mais un baron du crime n&#39;est pas limit&#233; de cette fa&#231;on. Dans le monde criminel, les relations qu&#39;un personnage construit, ses loyaut&#233;s et sa r&#233;putation sont les principaux &#233;l&#233;ments qui le maintiennent en vie.&lt;br /&gt;&lt;br /&gt;Les aventures explorant le monde criminel ont tendance &#224; impliquer des PJ non-Bons dont l&#39;objectif principal est d&#39;acqu&#233;rir de l&#39;argent et du pouvoir. Cependant, il est tout &#224; fait possible d&#39;avoir un groupe de hors-la-loi bien intentionn&#233;s, dans la veine de Robin des Bois, luttant contre un gouvernement corrompu ou essayant d&#39;aider les opprim&#233;s. Dans ce cas, naviguer dans le monde criminel est encore plus difficile et dangereux, car les PJs peuvent trouver que leurs scrupules moraux rendent plus difficiles le marchandage et l&#39;&#233;tablissement de la confiance et des r&#233;putations parmi les autres criminels.&lt;br /&gt;&lt;br /&gt;Une campagne criminelle engageante implique souvent des &lt;a class=&quot;pagelink&quot; href=&quot;Casses.html&quot; title=&quot;Les casses&quot;&gt;casses&lt;/a&gt;, des escroqueries et d&#39;autres manœuvres sournoises. Dans ce cas, l&#39;&#233;l&#233;ment Mesures et contre-mesures est mis en avant, et les PJs doivent rep&#233;rer les d&#233;fenses de leurs adversaires et &#233;laborer un plan pour les contourner ou exploiter leurs faiblesses.&lt;br /&gt;&lt;br /&gt;Dans une campagne sur ce th&#232;me, le monde myst&#233;rieux des criminels se cache sous la surface des lieux et des gens, m&#234;me les plus inoffensifs. Un groupe de gu&#233;risseurs bienveillants qui traverse les fronti&#232;res nationales pour aider &#224; soigner les &#233;pid&#233;mies peut contenir un &#233;l&#233;ment qui fait de la contrebande de substances alchimiques ill&#233;gales. Un sh&#233;rif r&#233;put&#233; pour avoir &#233;limin&#233; la plupart des gangs d&#39;une ville peut avoir travaill&#233; sous le patronage et avec l&#39;aide d&#39;un gang qui avait tout &#224; gagner &#224; s&#39;emparer du territoire et des op&#233;rations de ses rivaux. les PJs, en tant que personnes au courant, font l&#39;exp&#233;rience de ces dessous secrets o&#249; qu&#39;ils aillent et vivent dans ce royaume de l&#39;ombre aux mœurs obscures. M&#234;me s&#39;ils partent avec de bonnes intentions, il leur est facile de devenir cyniques vis-&#224;-vis du monde qui les entoure.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Guerre et propagande&lt;a class=&quot;headeranchor&quot; id=&quot;Guerre_et_propagande_7&quot; href=&quot;#Guerre_et_propagande_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Une campagne qui met en sc&#232;ne des guerres de propagande et d&#39;opinion publique est centr&#233;e sur L&#39;importance de l&#39;apparence, associ&#233;e aux &#233;l&#233;ments Marchandage et compromis et Le pouvoir des secrets. Dans une partie utilisant ce th&#232;me, les PJs cherchent &#224; influencer l&#39;opinion publique d&#39;une mani&#232;re particuli&#232;re. Ils peuvent &#234;tre des fixeurs politiques qui cherchent &#224; am&#233;liorer l&#39;image de leurs clients, ou des lobbyistes d&#39;un mouvement politique particulier qui tentent d&#39;obtenir un soutien pour ce mouvement. Dans un cas comme dans l&#39;autre, les PJs sont amen&#233;s &#224; g&#233;rer des informations (en particulier des secrets compromettants) et &#224; conclure des accords et des alliances temporaires afin de servir leur cause. Contrairement &#224; de nombreux autres types d&#39;aventures o&#249; les PJs doivent d&#233;couvrir un complot secret et inf&#226;me, dans une guerre de propagande, les PJs doivent d&#233;couvrir et d&#233;cider comment utiliser des secrets compromettants sur le camp adverse. Ils doivent &#233;galement enterrer leurs propres secrets et ceux de leurs alli&#233;s. Bien qu&#39;ils soient politiquement pr&#233;judiciables, ces secrets proviennent g&#233;n&#233;ralement de lois humanisantes ou d&#39;erreurs de jugement chez un alli&#233; par ailleurs respectable, plut&#244;t que d&#39;un alli&#233; activement malfaisant. Cependant, les PJs peuvent &#234;tre amen&#233;s &#224; faire un choix difficile si un personnage l&#233;gitimement m&#233;prisable leur offre le soutien dont ils ont besoin ou retient leurs services. Dans une guerre de propagande, les conflits sociaux sont presque in&#233;vitables, et comme le champ de bataille se situe dans le tribunal de l&#39;opinion publique, l&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Influence.html&quot; title=&quot;L&amp;#39;influence&quot;&gt;Influence&lt;/a&gt; et les &lt;a class=&quot;pagelink&quot; href=&quot;Duels-Verbaux.html&quot; title=&quot;Les duels verbaux&quot;&gt;duels verbaux&lt;/a&gt; sont &#233;galement susceptibles de jouer un r&#244;le.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Loi et Ordre&lt;a class=&quot;headeranchor&quot; id=&quot;Loi_et_Ordre_8&quot; href=&quot;#Loi_et_Ordre_8&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Dans une campagne o&#249; les personnages font partie du syst&#232;me de justice p&#233;nale, comme des d&#233;tectives ou des avocats, Mesures et contre-mesures et Le pouvoir des secrets sont les deux &#233;l&#233;ments d&#39;intrigue les plus importants. &#192; l&#39;instar des s&#233;ries t&#233;l&#233;vis&#233;es d&#39;investigation ou de tribunal, les jeux utilisant ce th&#232;me ont tendance &#224; &#234;tre quelque peu &#233;pisodiques par nature, avec un &quot;myst&#232;re de la semaine&quot; ou un &quot;cas de la semaine&quot;, bien qu&#39;ils aient toujours une intrigue importante qui r&#233;appara&#238;t tout au long de la campagne.&lt;br /&gt;&lt;br /&gt;Pour un groupe de d&#233;tectives, les myst&#232;res consistent &#224; d&#233;m&#234;ler les failles des contre-mesures des criminels contre la d&#233;tection, &#224; l&#39;image de la fa&#231;on dont les criminels cherchent &#224; d&#233;jouer les contre-mesures qui d&#233;fendent leurs cibles. Chaque myst&#232;re peut entra&#238;ner les d&#233;tectives plus profond&#233;ment dans un r&#233;seau d&#39;intrigues et de complots li&#233;s entre eux, et ils peuvent &#234;tre contraints de prendre une d&#233;cision difficile lorsque leurs enqu&#234;tes mettent &#224; jour des v&#233;rit&#233;s d&#233;rangeantes sur ceux qui les entourent.&lt;br /&gt;&lt;br /&gt;Les personnages avocats se plongent aussi souvent dans l&#39;investigation, mais ils se concentrent sur la recherche des faiblesses du dossier de leur adversaire. Une proc&#233;dure judiciaire devant un magistrat ou un jury peut impliquer un ou plusieurs &lt;a class=&quot;pagelink&quot; href=&quot;Duels-Verbaux.html&quot; title=&quot;Les duels verbaux&quot;&gt;duels verbaux&lt;/a&gt; entre les avocats, entrecoup&#233;s d&#39;enqu&#234;tes et d&#39;interactions entre les personnages impliqu&#233;s, l&#39;affaire elle-m&#234;me &#233;tant un conflit social plus large.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Intrigue ultime&lt;a class=&quot;headeranchor&quot; id=&quot;Intrigue_ultime_9&quot; href=&quot;#Intrigue_ultime_9&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Dans une campagne qui embrasse pleinement les divers &#233;l&#233;ments d&#39;intrigue, tous les th&#232;mes ci-dessus se rejoignent. D&#39;un c&#244;t&#233;, il y a les nobles intrigants qui cherchent &#224; prendre l&#39;avantage, et de l&#39;autre c&#244;t&#233;, les dessous du monde criminel, avec des gens comme des fixeurs politiques, des lobbyistes et les forces de l&#39;ordre, tous pris entre les deux - soutenant, utilisant et &#233;tant utilis&#233;s tour &#224; tour par les deux camps. Les PJs doivent naviguer dans ces mondes perfides, faire face &#224; des d&#233;cisions difficiles sur la fa&#231;on de g&#233;rer leurs all&#233;geances divis&#233;es ou de mettre de c&#244;t&#233; leurs diff&#233;rences pour faire face &#224; une menace commune.&lt;br /&gt;&lt;br /&gt;Supposons, par exemple, qu&#39;une duchesse mal&#233;fique, d&#233;sireuse d&#39;usurper le tr&#244;ne de son fr&#232;re a&#238;n&#233;, sollicite l&#39;aide d&#39;une grande famille criminelle, offrant une assistance magique aux malfaiteurs afin qu&#39;ils puissent assassiner une s&#233;rie de nobles sans laisser de preuves. Le groupe pourrait &#234;tre constitu&#233; de l&#39;alliance improbable du d&#233;tective charg&#233; d&#39;enqu&#234;ter sur les meurtres, du fils de l&#39;un des nobles assassin&#233;s et de la fille d&#39;un patron du crime rival. Tous les trois sont d&#233;termin&#233;s &#224; traverser la toile de l&#39;intrigue pour leurs propres raisons, mais chacun vient d&#39;un monde tellement diff&#233;rent qu&#39;il y a forc&#233;ment des tensions et des conflits lorsque ces mondes entrent en collision. Chacun d&#39;entre eux dispose de ressources et de contacts diff&#233;rents, qui seront tous n&#233;cessaires pour mettre &#224; jour l&#39;implication de la duchesse, puis passer outre ses mensonges et sa propagande pour prouver ce qu&#39;elle a fait au peuple et &#224; son fr&#232;re, le roi.
